// shattered-oath — эпический трейлер in C minor, 89 BPM. Generated by MathMusic
// (style epic, seed 1): prologue → main title → the fall → rising → build → charge → epilogue.
// Themes: A — Last Stand (последний бой) (recomposed), B — Banners (тема валторн) (as written); the bridge melody is newly
// composed on the rhythm of a theme from bossa. Computed parts: a counter-melody from the chords, a canon, a run up to the dominant in every build-up, the theme at half speed in the outro.
// It is an ordinary song file: change anything; the melodies can be drawn in the piano roll (P).
// x is time in beats; n counts semitones from C4 (MIDI 60).
import { TAU, delay, exp, filter, floor, hz, mod, noise, osc, reverb, sin, smooth, tanh } from '../src/engine.js'
import {
  arrangement, bowed, brass, chorus, crashCymbal, hash, improvise, notesAt, pan, pianoTone, poly, snareDrum, spiccatoTone, strings, taikoDrum, trigger,
} from '../src/instruments.js'

const SECTIONS = [[0,"prologue"],[16,"main title"],[48,"the fall"],[80,"rising"],[112,"build"],[128,"charge"],[192,"epilogue"]]
const END = 216
const part = arrangement(SECTIONS)
const is = (x, ...names) => names.includes(part(x).name)
const C4 = 440 * 2 ** (-9 / 12) // 261.63 Hz, exact equal temperament
const SW = 0.5 // the off-beat eighth lands at 0.5 of the beat
const ROLE = [[0,"intro",0],[16,"theme",2],[48,"bridge",1],[80,"themeB",2],[112,"build",2],[128,"final",3],[192,"outro",0]] // [start, role, energy 0–3] per section
const sectionOf = x => { let s = ROLE[0]; for (const r of ROLE) if (r[0] <= x) s = r; return s }
const energy = x => (x < END ? sectionOf(x)[2] : -1)
const role = x => (x < END ? sectionOf(x)[1] : 'end')

